#include <atomic>
#include <vector>
#include <thread>

int main() {
    std::atomic<int> counter{0};
    std::vector<std::thread> ts;
    for (int i = 0; i < 8; ++i) {
        ts.emplace_back([&] {
            for (int j = 0; j < 100'000; ++j) counter.fetch_add(1, std::memory_order_relaxed);
        });
    }
    for (auto& t : ts) t.join();
    return counter.load();   // 800000 — atomic, no lost updates
}

